import XCTest
@testable import GoodreadsGUI

final class GoodreadsSimilarTests: XCTestCase {
    func testParsesTheSimilarBooksPage() {
        let items = GoodreadsSimilar.parse(html: Self.page)
        XCTAssertEqual(items.map(\.bookID), ["44767458", "375802"])
        let ender = items[1]
        XCTAssertEqual(ender.title, "Ender’s Game (Ender's Saga, #1)")
        XCTAssertEqual(ender.author, "Orson Scott Card")
        XCTAssertEqual(ender.rating, 4.31)
        XCTAssertEqual(ender.ratingsCount, 1400053)
        XCTAssertEqual(ender.coverURL?.absoluteString.contains("._SY"), false, "a bigger cover than the thumbnail")
        XCTAssertTrue(ender.blurb?.hasPrefix("From New York Times") ?? false)
    }

    func testReadsTheJSONOnThePage() {
        let items = GoodreadsSimilar.parse(html: Self.props)
        XCTAssertGreaterThanOrEqual(items.count, 2)
        let ender = items.first { $0.bookID == "375802" }
        XCTAssertEqual(ender?.workID, "2422333")
        XCTAssertEqual(ender?.pages, 324)
        XCTAssertEqual(ender?.rating, 4.31)
        XCTAssertEqual(ender?.author, "Orson Scott Card")
        XCTAssertTrue(ender?.blurb?.contains("interstellar war") ?? false, "the whole description")
    }

